package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class VisualTextRoutingTest {
 final ObjectMapper json=new ObjectMapper();
 static Rule visual(String subject,String document){return new Rule("v",subject+"须在"+document+"盖章","VISUAL",subject,"seal","EXISTS","公章","",Map.of("documentType",document,"visualType","SEAL"),subject+"须在"+document+"盖章","",List.of());}
 Map<String,Object> run(List<Rule> rules,Document bid,Map<String,Object> context,AtomicInteger extracts){
  String requirement=rules.stream().map(Rule::sourceQuote).reduce((a,b)->a+"；"+b).orElseThrow();
  Checkpoint cp=new Checkpoint("cp","签章及材料","响应","HIGH","SEMANTIC_RESPONSE","","",requirement,"",true,true,true,null);
  ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "visual-routing-test";}public JsonNode request(String op,Map<String,Object> input){
   if(op.equals("COMPILE"))return json.valueToTree(Map.of("logic","ALL","rules",rules));
   assertEquals("EXTRACT",op);extracts.incrementAndGet();assertTrue(ExtractionBatches.rules(input).stream().noneMatch(r->r.predicate().equals("VISUAL")),"Text protocol must never receive a visual obligation");return json.valueToTree(Map.of("facts",List.of()));
  }};
  Map<String,Object> explicitCompilerContext=new HashMap<>(context);explicitCompilerContext.put("allowModelRuleCompilation",true);
  return new VerificationEngine(gateway,null).evaluate(cp,List.of(bid),null,explicitCompilerContext);
 }
 Map<String,Object> observation(){return linked("id","observed","obligationId","v","documentId","bid","location",1,"locationType","PAGE","imageHash","image","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",List.of(1,1,20,20),"source",Map.of("documentHash","sha","renderedSha256","image"),"authenticityVerified",false);}
 @Test void pureVisualOnlyRetrievesAndSchedulesImageWithoutTextExtraction(){AtomicInteger calls=new AtomicInteger();Map<String,Object> result=run(List.of(visual("甲公司","授权书")),VerificationEngineTest.doc("授权书\n甲公司（盖章）"),Map.of(),calls);assertEquals(0,calls.get());assertEquals("UNDETERMINED",result.get("businessDecision"));assertFalse(RuleEvaluator.maps(result.get("visualRequests")).isEmpty());assertTrue(RuleEvaluator.maps(result.get("steps")).stream().anyMatch(x->str(x,"type").startsWith("EVIDENCE_PLAN")));}
 @Test void unlocatedDocumentProducesScopeGapAndNoPretendImageTask(){AtomicInteger calls=new AtomicInteger();Map<String,Object> result=run(List.of(visual("甲公司","第六章投标文件格式")),VerificationEngineTest.doc("授权书\n甲公司（盖章）"),Map.of(),calls);assertEquals(0,calls.get());assertTrue(RuleEvaluator.maps(result.get("gaps")).stream().anyMatch(g->str(g,"code").equals("REQUIREMENT_VISUAL_SCOPE_UNRESOLVED")));assertTrue(RuleEvaluator.maps(result.get("visualRequests")).isEmpty());assertTrue(RuleEvaluator.maps(result.get("recoveryActions")).stream().anyMatch(g->str(g,"strategy").equals("REPAIR_REQUIREMENT")&&str(g,"reasonCode").equals("REQUIREMENT_VISUAL_SCOPE_UNRESOLVED")));}
 @Test void concreteSubjectObservedSealStillPassesWithoutTextCall(){AtomicInteger calls=new AtomicInteger();Map<String,Object> result=run(List.of(visual("甲公司","授权书")),VerificationEngineTest.doc("授权书\n甲公司（盖章）"),Map.of("visualObservations",List.of(observation())),calls);assertEquals("PASS",result.get("businessDecision"));assertEquals(0,calls.get());}
 @Test void cachedSourcedRoleBindingStillAllowsImageEvaluation(){AtomicInteger calls=new AtomicInteger();Document bid=VerificationEngineTest.doc("本项目授权书\n甲公司角色为投标人，授权书盖章位置");EvidenceCorpus c=new EvidenceCorpus(List.of(bid));Map<String,Object> fact=linked("id","role","kind","RELATION","subject","甲公司","field","角色","rawValue","投标人","value","投标人","unit","","basis","","scope","CURRENT_PROJECT","sourceIds",List.of(c.all.get(0).id()),"attributes",Map.of("object","投标人"));Map<String,Object> entry=SharedFactReuseTest.entry(c,fact);Map<String,Object> result=run(List.of(visual("投标人","授权书")),bid,Map.of("sharedFactLookup",(Function<Map<String,Object>,List<Map<String,Object>>>)(q)->List.of(entry),"visualObservations",List.of(observation())),calls);assertEquals("PASS",result.get("businessDecision"));assertEquals(0,calls.get());}
 @Test void independentMaterialAndRelationConditionsStillUseTextExtraction(){AtomicInteger calls=new AtomicInteger();Rule material=new Rule("m","甲公司须提交守法承诺书","MATERIAL","甲公司","材料","EXISTS","守法承诺书","",Map.of(),"甲公司须提交守法承诺书","",List.of());Rule relation=new Rule("r","甲公司角色为投标人","RELATION","甲公司","角色","=","投标人","",Map.of("object","投标人"),"甲公司角色为投标人","",List.of());Map<String,Object> result=run(List.of(visual("甲公司","授权书"),material,relation),VerificationEngineTest.doc("授权书\n甲公司（盖章）\n守法承诺书\n甲公司角色为投标人\n甲公司承诺遵守法律法规并履行本项目要求。"),Map.of(),calls);assertTrue(calls.get()>0);assertFalse(RuleEvaluator.maps(result.get("visualRequests")).isEmpty());}
 @Test void unresolvedLiteralRoleCannotBorrowObservedCompanySeal(){AtomicInteger calls=new AtomicInteger();Map<String,Object> result=run(List.of(visual("投标人","授权书")),VerificationEngineTest.doc("授权书\n甲公司（盖章）"),Map.of("visualObservations",List.of(observation())),calls);assertEquals("UNDETERMINED",result.get("businessDecision"));assertEquals(0,calls.get());assertTrue(RuleEvaluator.maps(result.get("gaps")).stream().anyMatch(g->str(g,"code").equals("SUBJECT_RELATION_UNPROVEN")));}
 @Test void explicitCurrentBidderLabelSuppliesPrerequisiteWithoutTextModel(){AtomicInteger calls=new AtomicInteger();Map<String,Object> observed=observation();observed.put("observedValue","北京甲有限公司");Map<String,Object> result=run(List.of(visual("投标人","授权书")),VerificationEngineTest.doc("本项目授权书\n投标人：北京甲有限公司\n法定代表人（签字）："),Map.of("visualObservations",List.of(observed)),calls);assertEquals("PASS",result.get("businessDecision"));assertEquals(0,calls.get());JsonNode relations=json.valueToTree(result.get("relations"));assertEquals("北京甲有限公司",relations.get(0).path("value").asText());assertEquals("EXPLICIT_BIDDER_LABEL",relations.get(0).path("attributes").path("bindingMethod").asText());}
 @Test void historicalTemplateAndUnscopedBidderLabelsCannotBorrowImage(){for(String text:List.of("历史项目\n投标人：北京甲有限公司\n授权书", "本项目授权书\n填写示例\n投标人：北京甲有限公司", "授权书\n投标人：北京甲有限公司", "本项目授权书\n非投标人：北京甲有限公司")){AtomicInteger calls=new AtomicInteger();Map<String,Object> observed=observation();observed.put("observedValue","北京甲有限公司");Map<String,Object> result=run(List.of(visual("投标人","授权书")),VerificationEngineTest.doc(text),Map.of("visualObservations",List.of(observed)),calls);assertEquals("UNDETERMINED",result.get("businessDecision"),text);assertEquals(0,calls.get());assertEquals(0,json.valueToTree(result.get("relations")).size(),text);}}
 @Test void explicitCurrentSignerLabelRetainsSignatureObservation(){AtomicInteger calls=new AtomicInteger();Rule rule=new Rule("v","法定代表人须在授权书签字","VISUAL","法定代表人","signature","EXISTS","签字","",Map.of("documentType","授权书","visualType","SIGNATURE"),"法定代表人须在授权书签字","",List.of());Map<String,Object> observed=observation();observed.put("type","SIGNATURE");observed.put("observedValue","张三");Map<String,Object> result=run(List.of(rule),VerificationEngineTest.doc("本项目授权书\n本项目法定代表人：张三\n签字位置"),Map.of("visualObservations",List.of(observed)),calls);assertEquals("PASS",result.get("businessDecision"));assertEquals(0,calls.get());}
 @Test void genericSignerLabelAndAlternativeNamesDoNotEstablishCurrentIdentity(){for(String text:List.of("授权书\n法定代表人：张三","本项目授权书\n本项目法定代表人：张三、李四","历史项目\n授权书\n本项目法定代表人：张三","本项目授权书\n法定代表人（或委托代理人）：张三")){Rule rule=new Rule("v","法定代表人须在授权书签字","VISUAL","法定代表人","signature","EXISTS","签字","",Map.of("documentType","授权书","visualType","SIGNATURE"),"法定代表人须在授权书签字","",List.of());Map<String,Object> observed=observation();observed.put("type","SIGNATURE");observed.put("observedValue","张三");Map<String,Object> result=run(List.of(rule),VerificationEngineTest.doc(text),Map.of("visualObservations",List.of(observed)),new AtomicInteger());assertEquals("UNDETERMINED",result.get("businessDecision"),text);assertEquals(0,json.valueToTree(result.get("relations")).size(),text);}}
}
